import Foundation
import GoogleSheets

/// A Google connection baked into the build, so a fresh install is already
/// connected (#78).
///
/// This app has exactly one user and one spreadsheet. Pasting a service-account
/// key by hand after every install — and every simulator wipe, which happens on
/// each screenshot run — is friction that buys nothing.
///
/// The payload is **gitignored** (`Config/DefaultConnection.json`, generated by
/// `scripts/set-default-connection.sh`) and only reaches the app as a bundled
/// resource at build time. The key therefore never enters git history, which is
/// the rule that matters: a repository gets cloned, backed up and scanned, and a
/// key in its history is there permanently.
///
/// It *is* inside the shipped bundle and can be extracted from an `.ipa`. That
/// is an accepted tradeoff for a personal build — see `docs/repeat-app-spec.md`
/// §4.1 — and the key must be rotated before any wider distribution.
enum DefaultConnection {
    static let resourceName = "DefaultConnection"

    /// Records that seeding has already run.
    ///
    /// Without it, "Видалити ключ" in Settings would be undone by the next cold
    /// launch: the Keychain would be empty again, seeding would fire again, and
    /// the owner could never actually disconnect.
    static let seededKey = "google.defaultConnectionSeeded"

    private static let spreadsheetIdKey = "google.spreadsheetId"

    enum Outcome: Equatable {
        /// No payload in the bundle — the ordinary state of a clean clone.
        case noPayload
        /// Already run once, or the owner already configured it by hand.
        case skipped
        case seeded(key: Bool, spreadsheetId: Bool)
        case failed(String)
    }

    static func payloadURL(in bundle: Bundle = .main) -> URL? {
        bundle.url(forResource: resourceName, withExtension: "json")
    }

    /// Seeds from the bundled payload if there is one and nothing is configured.
    @discardableResult
    static func seedIfNeeded(bundle: Bundle = .main,
                             defaults: UserDefaults = .standard) -> Outcome {
        seed(from: payloadURL(in: bundle), defaults: defaults)
    }

    /// The testable core. Takes the payload's location rather than a `Bundle` so
    /// a test can point it at a temporary file.
    @discardableResult
    static func seed(from url: URL?, defaults: UserDefaults = .standard) -> Outcome {
        guard let url, FileManager.default.fileExists(atPath: url.path) else { return .noPayload }
        guard !defaults.bool(forKey: seededKey) else { return .skipped }

        let payload: Payload
        do {
            payload = try Payload(contentsOf: url)
        } catch {
            // A malformed payload must not stop the app from launching: the
            // owner can still paste a key in Settings, which is exactly the
            // behaviour they had before this existed.
            return .failed(String(describing: error))
        }

        var seededKeychain = false
        do {
            if try CredentialStore.load() == nil {
                try CredentialStore.save(json: payload.serviceAccountJSON)
                seededKeychain = true
            }
        } catch {
            // Deliberately *before* the marker is set, so a failure is not
            // permanent. Both realistic causes are recoverable: a background
            // launch before the device's first unlock, where the Keychain is
            // simply not readable yet, and a payload the owner fixes and
            // rebuilds. Burning the one shot here would mean the app never
            // connects and never says why.
            return .failed(String(describing: error))
        }

        // Past this line the connection is as configured as it is going to get,
        // so record it. Everything after is idempotent bookkeeping.
        defaults.set(true, forKey: seededKey)

        // An id the owner typed by hand outranks the baked-in one.
        var seededId = false
        let existing = (defaults.string(forKey: spreadsheetIdKey) ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if existing.isEmpty, !payload.spreadsheetId.isEmpty {
            defaults.set(payload.spreadsheetId, forKey: spreadsheetIdKey)
            seededId = true
        }

        guard seededKeychain || seededId else { return .skipped }
        return .seeded(key: seededKeychain, spreadsheetId: seededId)
    }

    /// Only for tests and for `-resetDefaultConnectionOnLaunch`.
    static func forgetSeeding(defaults: UserDefaults = .standard) {
        defaults.removeObject(forKey: seededKey)
    }

    // MARK: - Payload

    struct Payload {
        let spreadsheetId: String
        /// The service-account object re-serialised, because `CredentialStore`
        /// stores and validates the owner's original JSON rather than a lossy
        /// projection of it.
        let serviceAccountJSON: String

        enum PayloadError: Error, CustomStringConvertible {
            case notAnObject
            case missingServiceAccount

            var description: String {
                switch self {
                case .notAnObject: "DefaultConnection.json is not a JSON object."
                case .missingServiceAccount: "DefaultConnection.json has no \"serviceAccount\" object."
                }
            }
        }

        init(contentsOf url: URL) throws {
            let data = try Data(contentsOf: url)
            guard let root = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
                throw PayloadError.notAnObject
            }
            guard let account = root["serviceAccount"] as? [String: Any] else {
                throw PayloadError.missingServiceAccount
            }
            let accountData = try JSONSerialization.data(withJSONObject: account)
            self.serviceAccountJSON = String(decoding: accountData, as: UTF8.self)
            self.spreadsheetId = SheetsSettings.extractSpreadsheetId(
                from: (root["spreadsheetId"] as? String) ?? ""
            )
        }
    }
}
